/* THEME BASELINE STYLES
------------------------------------------------------------------------------*/
body{
  background-color: var(--bg-body);
  font-size: var(--body-md-font-size);
  color: var(--text-content);
  font-family: var(--body-md-font-family);
  font-weight: var(--body-md-font-weight);
  line-height: var(--body-md-line-height);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--wp--preset--font-family--system-sans-serif);
}

a:where(:not(.wp-element-button)){
  color: var(--interactive);
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
}

a:where(:not(.wp-element-button)):hover{
  -webkit-text-decoration-line: none;
  text-decoration-line: none;
}

a:where(:not(.wp-element-button)):active{
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
}

.aligncenter {
  display: block;
  margin-left: auto;
  margin-right: auto;
}

@media (min-width: 1536px) {
  .container main {
    max-width: var(--wp--style--global--content-size) !important;
  }
}
@media (min-width: 1536px) and (max-width: 1556px) {
  .container{
    padding-left: 0.75rem;
    padding-right: 0.75rem;
  }
}
@media (min-width: 1280px) and (max-width: 1300px) {
  .container{
    padding-left: 0.75rem;
    padding-right: 0.75rem;
  }
}
@media (min-width: 1024px) and (max-width: 1044px) {
  .container{
    padding-left: 0.75rem;
    padding-right: 0.75rem;
  }
}
@media (min-width: 768px) and (max-width: 788px) {
  .container{
    padding-left: 0.75rem;
    padding-right: 0.75rem;
  }
}

/* AlpineJS Helpers */
[x-cloak] {
  display: none !important;
}

#wpadminbar {
  max-width: 100% !important;
}

/* Accessibility helper */
.webaim-hidden{
  position: absolute !important;
  margin: -1px !important;
  height: 1px !important;
  width: 1px !important;
  overflow: hidden !important;
  white-space: nowrap !important;
  border-width: 0px !important;
  padding: 0px !important;
  clip: rect(0, 0, 0, 0);
}

/* COMPONENTS STYLES
------------------------------------------------------------------------------*/
.accordion-item{
  margin-bottom: 0.5rem;
  border-color: var(--border-light);
  padding: var(--space-150);
  font-size: var(--body-md-font-size);
  font-family: var(--body-md-font-family);
  font-weight: var(--body-md-font-weight);
  line-height: var(--body-md-line-height);
}
.accordion-item:hover{
  cursor: pointer;
}
.component-sidebar-contextual-nav__accordion .accordion-item{
  margin-bottom: 0px;
  padding: var(--space-100);
}
.accordion-item:last-child{
  margin-bottom: 0px;
}
.accordion-item__body{
  margin-top: var(--space-250);
  padding-right: 3rem;
}
.component-sidebar-contextual-nav__accordion .accordion-item__body{
  margin-top: var(--space-100);
}
.accordion-item__body ul{
  list-style-type: disc;
  -webkit-padding-start: 2.5rem;
  padding-inline-start: 2.5rem;
}
.accordion-item__body ul li{
  margin-bottom: 0.5rem;
}
.accordion-item__body ol{
  list-style-type: decimal;
  -webkit-padding-start: 2.5rem;
  padding-inline-start: 2.5rem;
}
.accordion-item__body ol li{
  margin-bottom: 0.5rem;
}
.accordion-item__title{
  font-size: var(--body-md-font-size);
  font-family: var(--body-md-font-family);
  font-weight: var(--body-md-font-weight);
  line-height: var(--body-md-line-height);
}
.accordion-item__title a{
  color: var(--text-content);
  -webkit-text-decoration-line: none;
  text-decoration-line: none;
}
.component-sidebar-contextual-nav__accordion .accordion-item__title a{
  font-weight: 700;
  color: var(--nav-contextual-link-lvl-1);
}
.component-sidebar-contextual-nav__accordion .accordion-item__title a:hover{
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
}
.accordion-item__icon{
  margin-left: 1rem;
  color: var(--interactive);
}
.open .accordion-item__icon{
  color: var(--highlight-dark);
}
.accordion-item.open{
  border-color: var(--highlight-dark);
  background-color: var(--highlight-light);
